import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256[] calldata v) public {
        // Bound inputs to avoid overflow in the loop (assuming array lengths are small)
        vm.assume(_tos.length <= 10 && v.length == _tos.length);
        vm.assume(v.length > 0);
        uint256 sumV = 0;
        for (uint i = 0; i < v.length; i++) {
            sumV += v[i];
        }

        // Record balance before transfer
        uint256 balanceBefore = address(this).balance;

        // Execute the transfer - note: the contract does not hold any ETH initially
        c.transfer(from, caddress, _tos, v);

        // After the call, the contract's ETH balance should remain unchanged
        assertTrue(address(this).balance == balanceBefore);
    }
}
